  3193	/**
  3194	 * @brief 只读打印 SD 时钟拓扑，用来确认 SD 到底挂在哪条时钟分支上。
  3195	 *
  3196	 * @details 背景：52x 的 HPSYS_RCC_CSR 里没有 SEL_SDMMC（只有 SEL_MPI1/2、
  3197	 *          SEL_PERI/TICK/USBC），但硬件图上 SD 和 MPI 共用 `CG MPI1/2`
  3198	 *          那一路时钟门。所以"SD 的父时钟是谁"要靠寄存器现场判断：
  3199	 *            - sel_mpi1/sel_mpi2 现在选的是 SYSCLK 还是 DLL2/DLL3；
  3200	 *            - CLKCR 的 DIV 反推出来的 SDCLK 是否等于 bus_hz。
  3201	 *          本函数**只读**，不动任何寄存器，也不改任何状态。
  3202	 *
  3203	 *          注意：这块板子上 HCLK == SYSCLK，所以"挂在 HCLK"和"挂在这条
  3204	 *          mux 输出上"从频率上分辨不出来 —— 必须直接读 CSR。
  3205	 */
  3206	void sf32lb_sd_clk_probe(void)
  3207	{
  3208	  uint32_t csr = hwp_hpsys_rcc->CSR;
  3209	  uint32_t enr2 = hwp_hpsys_rcc->ENR2;
  3210	  uint32_t clkcr = hwp_sdmmc1->CLKCR;
  3211	  uint32_t div = ((clkcr & SD_CLKCR_DIV_Msk) >> SD_CLKCR_DIV_Pos) + 1u;
  3212	  uint32_t hclk = HAL_RCC_GetHCLKFreq(CORE_ID_HCPU);
  3213	  uint32_t sc = HAL_RCC_GetSysCLKFreq(CORE_ID_HCPU);
  3214	
  3215	  syslog(LOG_INFO, "SDCLK: CSR=0x%08lx mpi1=%lu(%s) mpi2=%lu(%s) usbc=%lu peri=%lu tick=%lu\n",
  3216	         (unsigned long)csr,
  3217	         (unsigned long)((csr & HPSYS_RCC_CSR_SEL_MPI1_Msk) >> HPSYS_RCC_CSR_SEL_MPI1_Pos),
  3218	         sd_clk_src_name((csr & HPSYS_RCC_CSR_SEL_MPI1_Msk) >> HPSYS_RCC_CSR_SEL_MPI1_Pos),
  3219	         (unsigned long)((csr & HPSYS_RCC_CSR_SEL_MPI2_Msk) >> HPSYS_RCC_CSR_SEL_MPI2_Pos),
  3220	         sd_clk_src_name((csr & HPSYS_RCC_CSR_SEL_MPI2_Msk) >> HPSYS_RCC_CSR_SEL_MPI2_Pos),
  3221	         (unsigned long)((csr & HPSYS_RCC_CSR_SEL_USBC_Msk) >> HPSYS_RCC_CSR_SEL_USBC_Pos),
  3222	         (unsigned long)((csr & HPSYS_RCC_CSR_SEL_PERI_Msk) >> HPSYS_RCC_CSR_SEL_PERI_Pos),
  3223	         (unsigned long)((csr & HPSYS_RCC_CSR_SEL_TICK_Msk) >> HPSYS_RCC_CSR_SEL_TICK_Pos));
  3224	
  3225	  syslog(LOG_INFO, "SDCLK: dll2=%lu Hz enr2=0x%08lx sdmmc1_gate=%lu hclk=%lu sysclk=%lu\n",
  3226	         (unsigned long)HAL_RCC_HCPU_GetDLL2Freq(), (unsigned long)enr2,
  3227	         (unsigned long)((enr2 & HPSYS_RCC_ENR2_SDMMC1_Msk) ? 1u : 0u),
  3228	         (unsigned long)hclk, (unsigned long)sc);
  3229	
  3230	  syslog(LOG_INFO, "SDCLK: clkcr=0x%08lx stop=%lu voidfifo=%lu tune=%lu div=%lu -> %lu kHz if parent=HCLK\n",
  3231	         (unsigned long)clkcr,
  3232	         (unsigned long)((clkcr & SD_CLKCR_STOP_CLK_Msk) ? 1u : 0u),
  3233	         (unsigned long)((clkcr & SD_CLKCR_VOID_FIFO_ERROR_Msk) ? 1u : 0u),
  3234	         (unsigned long)((clkcr & SD_CLKCR_CLK_TUNE_SEL_Msk) >> SD_CLKCR_CLK_TUNE_SEL_Pos),
  3235	         (unsigned long)div, (unsigned long)(hclk / div / 1000u));
  3236	
  3237	  syslog(LOG_INFO, "SDCLK: pcr=0x%08lx cdr=0x%08lx bus_hz=%u kHz rca=0x%04x\n",
  3238	         (unsigned long)hwp_sdmmc1->PCR, (unsigned long)hwp_sdmmc1->CDR,
  3239	         (unsigned)(g_sd_bus_hz / 1000u), g_sd_rca);
  3240	}
