  3242	void sf32lb_sd_reclock(void)
  3243	{
  3244	  uint32_t div_before;
  3245	  uint32_t div_after;
  3246	  bool held;
  3247	
  3248	  if (!g_sd_initialized)
  3249	    {
  3250	      return;
  3251	    }
  3252	
  3253	  held = g_sd_clk_held;
  3254	  g_sd_clk_held = false;
  3255	
  3256	  if (!held)
  3257	    {
  3258	      nxmutex_lock(&g_sd_lock);
  3259	      div_before = ((hwp_sdmmc1->CLKCR & SD_CLKCR_DIV_Msk) >> SD_CLKCR_DIV_Pos) + 1u;
  3260	    }
  3261	  else
  3262	    {
  3263	      /* 停钟时 DIV 字段读到的是 0，用 clk_hold 存下来的真值。 */
  3264	      div_before = g_sd_div_held_before;
  3265	    }
  3266	
  3267	  sd1_set_clock(g_sd_bus_hz);  /* 结尾清 STOP_CLK，即放钟 */
  3268	  div_after = ((hwp_sdmmc1->CLKCR & SD_CLKCR_DIV_Msk) >> SD_CLKCR_DIV_Pos) + 1u;
  3269	  nxmutex_unlock(&g_sd_lock);
  3270	
  3271	  /* 每次 DVFS 跳档都会走到这里，DIV 必变。这行是"跳档 ↔ SD 时钟"的
  3272	   * 关联证据：以后再出 SD 失败，可以用它对手上的失败时刻。
  3273	   *
  3274	   * 只报 wait（等 g_sd_lock 花了多久），**不报 SDCLK 停了多久** ——
  3275	   * clk_hold 到 reclock 之间夹着 HAL_RCC_HCPU_ConfigHCLK，而
  3276	   * sifli_systick_reclock() 会在中间改 SysTick 的时基，sd1_mono_us() 跨过
  3277	   * 那一点测出来的差值是无意义的（现场打出过 1271310319 ms）。wait 全程
  3278	   * 在切换之前测量，所以是可信的。
  3279	   */
  3280	  if (held)
  3281	    {
  3282	      syslog(LOG_INFO,
  3283	             "SD: clk div %lu -> %lu (SDCLK %lu kHz) wait=%u ms\n",
  3284	             (unsigned long)div_before, (unsigned long)div_after,
  3285	             (unsigned long)(g_sd_bus_hz / 1000u),
  3286	             (unsigned)g_sd_hold_wait_ms);
  3287	    }
  3288	  else if (div_before != div_after)
  3289	    {
  3290	      syslog(LOG_INFO, "SD: clk div %lu -> %lu (SDCLK %lu kHz)\n",
  3291	             (unsigned long)div_before, (unsigned long)div_after,
  3292	             (unsigned long)(g_sd_bus_hz / 1000u));
  3293	    }
  3294	}
