  3505	/* Halve the card clock twice and re-measure. If the per-sector cost tracks the
  3506	 * clock we are bus-limited (the divider or its source clock is wrong); if it
  3507	 * barely moves, the cost is fixed per-CMD17 latency and only multi-block
  3508	 * transfers can help.
  3509	 */
  3510	
  3511	static void sf32lb_sd_bench_clocks(FAR struct mtd_dev_s *mtd,
  3512	                                   FAR uint8_t *buf)
  3513	{
  3514	  static const uint32_t hz[] =
  3515	  {
  3516	    SF32LB_SD_TRAN_CLOCK_HZ,
  3517	    SF32LB_SD_TRAN_CLOCK_HZ / 2,
  3518	    SF32LB_SD_TRAN_CLOCK_HZ / 4
  3519	  };
  3520	
  3521	  uint32_t hclk = HAL_RCC_GetHCLKFreq(CORE_ID_HCPU);
  3522	  unsigned int i;
  3523	
  3524	  for (i = 0; i < sizeof(hz) / sizeof(hz[0]); i++)
  3525	    {
  3526	      uint64_t t0;
  3527	      uint64_t dt;
  3528	      ssize_t ret = 0;
  3529	      uint32_t div;
  3530	      int j;
  3531	
  3532	      nxmutex_lock(&g_sd_lock);
  3533	      sd1_set_clock(hz[i]);
  3534	      div = ((hwp_sdmmc1->CLKCR & SD_CLKCR_DIV_Msk) >>
  3535	             SD_CLKCR_DIV_Pos) + 1;
  3536	      nxmutex_unlock(&g_sd_lock);
  3537	
  3538	      t0 = sf32lb_sd_now_us();
  3539	      for (j = 0; j < 32 && ret >= 0; j++)
  3540	        {
  3541	          ret = MTD_BREAD(mtd, j, 1, buf);
  3542	        }
  3543	
  3544	      dt = sf32lb_sd_now_us() - t0;
  3545	      syslog(LOG_INFO,
  3546	             "SDPROF: clk  div=%-3lu (~%lu kHz) %lu us/sector%s\n",
  3547	             (unsigned long)div,
  3548	             (unsigned long)(hclk / div / 1000),
  3549	             (unsigned long)(dt / 32),
  3550	             ret < 0 ? " READ FAILED" : "");
  3551	    }
  3552	
  3553	  nxmutex_lock(&g_sd_lock);
  3554	  sd1_set_clock(g_sd_bus_hz);
  3555	  nxmutex_unlock(&g_sd_lock);
  3556	}
