   739	/* DSR[0] is DAT0 last-level.  After a write the card holds DAT0 low while
   740	 * it programs; SD_SR_DATA_BUSY is only the host TX engine.  Identify samples
   741	 * idle DAT0 — if it is not high, skip this poll so a dead DSR cannot stall
   742	 * every block for WRITE_MAX_US.
   743	 */
   744	
   745	static bool sd1_dat0_ready(void)
   746	{
   747	  if (!g_sd_dat0_poll)
   748	    {
   749	      return true;
   750	    }
   751	
   752	  return (hwp_sdmmc1->DSR & 1u) != 0;
   753	}
   754	
   755	/**
   756	 * @brief PIO 忙等循环的“让出 + 喂狗”节拍器，每 1 ms 触发一次。
   757	 *
   758	 * @details
   759	 * 下面几个等待都是**轮询卡的状态位**（等 DAT0 编程忙、等 DATA_DONE、
   760	 * 等 DATA_BUSY），没有中断可用，所以轮询耗掉的时间必然记在发起 I/O 的那个
   761	 * 线程头上 —— 这不是"等"、是实打实的 CPU。
   762	 *
   763	 * 原先只有 `sd1_wait_dat0()` 会 `sched_yield()` + 喂狗，而
   764	 * `sd1_wait_write()` / `sd1_wait_card_idle()` 是**纯自旋**，上界
   765	 * `SF32LB_SD_WRITE_MAX_US` = 2 s。调用者优先级高于被饿住的那些任务时，
   766	 * 这 2 s 里它们一个都跑不到 —— 具体到本板：diag 线程 pri=9 每 500 ms 往
   767	 * SD 上的 LittleFS 刷日志（`myvendor_diaglog_flush()`），卡一慢就会把
   768	 * `ble_companion`(pri=8) 和 IDLE(0) 饿住。三个等待统一走这个节拍器。
   769	 *
   770	 * @param[in,out] next_yield 下次让出的时刻；调用方进入循环前初始化一次。
   771	 */
   772	static void sd1_spin_yield(uint64_t *next_yield)
   773	{
   774	  uint64_t now = sd1_mono_us();
   775	
   776	  if (now >= *next_yield)
   777	    {
   778	      myvendor_watchdog_work_beat();
   779	      sched_yield();
   780	      *next_yield = now + 1000u;
   781	    }
   782	}
   783	
   784	static uint8_t sd1_wait_dat0(uint64_t timeout_us)
   785	{
   786	  uint64_t deadline;
   787	  uint64_t next_yield;
   788	
   789	  if (!g_sd_dat0_poll)
   790	    {
   791	      return SD_SUCCESS;
   792	    }
   793	
   794	  deadline = sd1_mono_us() + timeout_us;
   795	  next_yield = sd1_mono_us() + 1000u;
   796	  while (!sd1_dat0_ready())
   797	    {
   798	      uint64_t now = sd1_mono_us();
   799	
   800	      if (now >= deadline)
   801	        {
   802	          g_sd_last_sr = hwp_sdmmc1->SR;
   803	          g_sd_diag.dat0_to++;
   804	          return SD_TIMEOUT;
   805	        }
   806	
   807	      sd1_spin_yield(&next_yield);
   808	    }
   809	
   810	  return SD_SUCCESS;
   811	}
   812	
   813	static uint8_t sd1_wait_write(void)
   814	{
   815	  /* Must wait on the error bits too, not just DATA_DONE: on a write CRC or
   816	   * data timeout the controller may never assert DATA_DONE, which previously
   817	   * spun this loop forever and hung the whole SD-backed filesystem.
   818	   */
   819	
   820	  uint32_t mask = SD_SR_DATA_DONE | SD_SR_DATA_TIMEOUT | SD_SR_DATA_CRC |
   821	                  SD_SR_FIFO_UNDERRUN;
   822	  uint64_t deadline = sd1_mono_us() + SF32LB_SD_WRITE_MAX_US;
   823	  uint64_t next_yield = sd1_mono_us() + 1000u;
   824	
   825	  while ((hwp_sdmmc1->SR & mask) == 0)
   826	    {
   827	      if (sd1_mono_us() >= deadline)
   828	        {
   829	          g_sd_last_sr = hwp_sdmmc1->SR;
   830	          hwp_sdmmc1->DCR = 0;
   831	          hwp_sdmmc1->SR = 0xffffffff;
   832	          g_sd_diag.wr_timeout++;
   833	          return SD_TIMEOUT;
   834	        }
   835	
   836	      /* 没有这句就是纯自旋最长 2 s：优先级低于调用者的任务全被饿住。 */
   837	      sd1_spin_yield(&next_yield);
   838	    }
   839	
   840	  hwp_sdmmc1->SR = SD_SR_DATA_DONE;
   841	  if (hwp_sdmmc1->SR & SD_SR_DATA_TIMEOUT)
   842	    {
   843	      g_sd_last_sr = hwp_sdmmc1->SR;
   844	      g_sd_diag.wr_timeout++;
   845	      return SD_TIMEOUT;
   846	    }
   847	
   848	  if (hwp_sdmmc1->SR & (SD_SR_DATA_CRC | SD_SR_FIFO_UNDERRUN))
   849	    {
   850	      g_sd_last_sr = hwp_sdmmc1->SR;
   851	      g_sd_diag.wr_crc++;
   852	      return SD_CRCERR;
   853	    }
   854	
   855	  if (sd1_wait_card_idle() != SD_SUCCESS)
   856	    {
   857	      return SD_TIMEOUT;
   858	    }
   859	
   860	  return sd1_wait_dat0(SF32LB_SD_WRITE_MAX_US);
   861	}
