   863	/* SiFli RT-Thread drv_sdio.c waits SD_SR_DATA_BUSY (HW_SDIO_IT_TXACT) after
   864	 * every data transfer.  That bit is the host data engine, not card DAT0.
   865	 * After it clears, sd1_wait_dat0() waits for programming busy.
   866	 */
   867	
   868	#define SF32LB_SD_BUSY_US  SF32LB_SD_WRITE_MAX_US
   869	
   870	static uint8_t sd1_wait_card_idle(void)
   871	{
   872	  uint64_t deadline = sd1_mono_us() + SF32LB_SD_BUSY_US;
   873	  uint64_t next_yield = sd1_mono_us() + 1000u;
   874	
   875	  while ((hwp_sdmmc1->SR & SD_SR_DATA_BUSY) != 0)
   876	    {
   877	      if (sd1_mono_us() >= deadline)
   878	        {
   879	          return SD_TIMEOUT;
   880	        }
   881	
   882	      /* 同上：没有这句就是纯自旋最长 2 s。 */
   883	      sd1_spin_yield(&next_yield);
   884	    }
   885	
   886	  return SD_SUCCESS;
   887	}
