  1977	 * @brief CMD12 STOP_TRANSMISSION（R1b）。
  1978	 * @details CMD18/CMD25 之后必须发；CMD17/CMD24 超时若把卡留在 DATA 也要发。
  1979	 */
  1980	static int sf32lb_sd_cmd12(void)
  1981	{
  1982	  uint8_t r = sd1_send_cmd(12, 0);
  1983	
  1984	  (void)sd1_wait_card_idle();
  1985	  (void)sd1_wait_dat0(SF32LB_SD_WRITE_MAX_US);
  1986	  return (r == SD_SUCCESS) ? OK : -EIO;
