  1989	/* HAL_GetTick()/uwTick is not advanced under NuttX, so HAL_DMA_PollForTransfer
  1990	 * cannot time out.  Wait on the TC flag with our own clock, then let HAL
  1991	 * do channel-unlock cleanup (Timeout 0 is fine once TC is already set).
  1992	 */
  1993	
  1994	static uint8_t sf32lb_sd_dma_wait(FAR DMA_HandleTypeDef *hdma, bool is_write,
  1995	                                 uint64_t timeout_us)
  1996	{
  1997	  uint32_t tc;
  1998	  uint32_t te;
  1999	  uint32_t err_mask = SD_SR_DATA_TIMEOUT | SD_SR_DATA_CRC |
  2000	                      SD_SR_STARTBIT_ERROR |
  2001	                      (is_write ? SD_SR_FIFO_UNDERRUN : SD_SR_FIFO_OVERRUN);
  2002	  uint64_t deadline = sd1_mono_us() + timeout_us;
  2003	
  2004	  tc = DMA_FLAG_TC1 << (hdma->ChannelIndex & 0x1cU);
  2005	  te = DMA_FLAG_TE1 << (hdma->ChannelIndex & 0x1cU);
  2006	
  2007	  while ((hdma->DmaBaseAddress->ISR & tc) == 0)
  2008	    {
  2009	      if ((hdma->DmaBaseAddress->ISR & te) != 0)
  2010	        {
  2011	          (void)HAL_DMA_Abort(hdma);
  2012	          if (is_write)
  2013	            {
  2014	              g_sd_diag.wr_crc++;
  2015	            }
  2016	          else
  2017	            {
  2018	              g_sd_diag.rd_crc++;
  2019	            }
  2020	
  2021	          return SD_CRCERR;
  2022	        }
  2023	
  2024	      if ((hwp_sdmmc1->SR & err_mask) != 0)
  2025	        {
  2026	          (void)HAL_DMA_Abort(hdma);
  2027	          if ((hwp_sdmmc1->SR & SD_SR_DATA_TIMEOUT) != 0)
  2028	            {
  2029	              if (is_write)
  2030	                {
  2031	                  g_sd_diag.wr_timeout++;
  2032	                }
  2033	              else
  2034	                {
  2035	                  g_sd_diag.rd_timeout++;
  2036	                }
  2037	
  2038	              return SD_TIMEOUT;
  2039	            }
  2040	
  2041	          if (is_write)
  2042	            {
  2043	              g_sd_diag.wr_crc++;
  2044	            }
  2045	          else
  2046	            {
  2047	              g_sd_diag.rd_crc++;
  2048	            }
  2049	
  2050	          return SD_CRCERR;
  2051	        }
  2052	
  2053	      if (sd1_mono_us() >= deadline)
  2054	        {
  2055	          (void)HAL_DMA_Abort(hdma);
  2056	          if (is_write)
  2057	            {
  2058	              g_sd_diag.wr_timeout++;
  2059	            }
  2060	          else
  2061	            {
  2062	              g_sd_diag.rd_timeout++;
  2063	            }
  2064	
  2065	          return SD_TIMEOUT;
  2066	        }
  2067	    }
  2068	
  2069	  if (HAL_DMA_PollForTransfer(hdma, HAL_DMA_FULL_TRANSFER, 0) != HAL_OK)
  2070	    {
  2071	      (void)HAL_DMA_Abort(hdma);
  2072	      if (is_write)
  2073	        {
  2074	          g_sd_diag.wr_timeout++;
  2075	        }
  2076	      else
  2077	        {
  2078	          g_sd_diag.rd_timeout++;
  2079	        }
  2080	
  2081	      return SD_TIMEOUT;
  2082	    }
  2083	
  2084	  return SD_SUCCESS;
  2085	}
