  4958	static bool map_page_gpx_plan_window(map_page_t * page, double from_lon,
  4959	    double from_lat, double from_along_m, bool reroute)
  4960	{
  4961	    double dest_along;
  4962	    double to_lon;
  4963	    double to_lat;
  4964	
  4965	    if (!page || !page->nav_gpx_pts || page->nav_gpx_n < 2u) {
  4966	        return false;
  4967	    }
  4968	    if (from_along_m < 0.0) {
  4969	        from_along_m = 0.0;
  4970	    }
  4971	    dest_along = from_along_m + VMAP_NAV_GPX_WINDOW_M;
  4972	    if (dest_along > page->nav_gpx_total_m) {
  4973	        dest_along = page->nav_gpx_total_m;
  4974	    }
  4975	    if (dest_along - from_along_m < 20.0) {
  4976	        return false;
  4977	    }
  4978	    if (fabs(dest_along - page->nav_gpx_win_end_m) < 50.0 && reroute) {
  4979	        return false;
  4980	    }
  4981	    if (!map_page_gpx_point_at(page->nav_gpx_pts, page->nav_gpx_n, dest_along,
  4982	            &to_lon, &to_lat)) {
  4983	        return false;
  4984	    }
  4985	    page->nav_gpx_win_start_m = from_along_m;
  4986	    page->nav_gpx_win_end_m = dest_along;
  4987	    page->nav_gpx_dense = false;
  4988	    page->nav_gpx_sparse = true;
  4989	    if (!map_page_nav_plan_begin(page, from_lon, from_lat, to_lon, to_lat, true,
  4990	            reroute)) {
  4991	        return false;
  4992	    }
  4993	    page->nav_gpx_sparse = true;
  4994	    VMAP_NAV_LOG("gpx sparse%s along=%.0f -> %.0f / %.0f",
  4995	        reroute ? " next" : "", from_along_m, dest_along, page->nav_gpx_total_m);
  4996	    return true;
  4997	}
  4998	
  4999	static bool map_page_gpx_tick_window(map_page_t * page,
  5000	    const vmap_route_nav_state_t * st, double lon, double lat)
  5001	{
  5002	    double along;
  5003	    double dist = 0.0;
  5004	    bool arrived;
  5005	    bool need;
  5006	
  5007	    if (!page || !st || !st->active || page->nav_planning
  5008	        || page->nav_gpx_rejoining || page->nav_review
  5009	        || !page->nav_gpx_pts || page->nav_gpx_n < 2u) {
  5010	        return false;
  5011	    }
  5012	    if (st->off_route_m > map_page_gpx_window_max_off_m(page)) {
  5013	        return false;
  5014	    }
  5015	    if (page->nav_gpx_win_end_m + 20.0 >= page->nav_gpx_total_m
  5016	        && st->remain_m > VMAP_ROUTE_ARRIVE_M) {
  5017	        return false;
  5018	    }
  5019	
  5020	    arrived = vmap_route_nav_is_arrived(st);
  5021	    need = arrived || st->remain_m <= VMAP_NAV_GPX_RELOAD_M;
  5022	    if (!need) {
  5023	        return false;
  5024	    }
  5025	    if (page->nav_gpx_win_end_m + 20.0 >= page->nav_gpx_total_m && arrived) {
  5026	        return false;
  5027	    }
  5028	
  5029	    along = map_page_gpx_nearest_along(page->nav_gpx_pts, page->nav_gpx_n,
  5030	        lon, lat, &dist);
  5031	    if (dist > VMAP_NAV_GPX_JOIN_MAX_M) {
  5032	        return false;
  5033	    }
  5034	    if (page->nav_gpx_dense) {
  5035	        double from_m = along;
  5036	
  5037	        if (from_m > VMAP_NAV_GPX_OVERLAP_M) {
  5038	            from_m -= VMAP_NAV_GPX_OVERLAP_M;
  5039	        } else {
  5040	            from_m = 0.0;
  5041	        }
  5042	        return map_page_gpx_load_window(page, from_m, false);
  5043	    }
  5044	    if (page->nav_gpx_sparse) {
  5045	        return map_page_gpx_plan_window(page, lon, lat, along, true);
  5046	    }
  5047	    return false;
  5048	}
