  5066	/**
  5067	 * @brief 打开 GPX：一次只加载前方 N km，接近窗口末端再动态续载。
  5068	 */
  5069	bool map_page_nav_from_gpx(map_page_t * page, const char * path, bool reverse)
  5070	{
  5071	    vmap_route_pt_t * pts;
  5072	    uint32_t kept = 0;
  5073	    uint32_t file_n = 0;
  5074	    double len = 0.0;
  5075	    double true_len = 0.0;
  5076	    double avg_m;
  5077	    bicycle_gnss_fix_t fix;
  5078	    bool have_fix;
  5079	    bool join;
  5080	    double from_m;
  5081	    bool ok;
  5082	
  5083	    if (!page || !path || path[0] == '\0') {
  5084	        return false;
  5085	    }
  5086	
  5087	    /* 同 map_page_show_gpx：判死时先返回，别在一定会失败的加载之前先停模拟、
  5088	     * 退 review、改标题与箭头（Codex R1 P2-9）。 */
  5089	    if (sf32lb_sd_dead != NULL && sf32lb_sd_dead()) {
  5090	        return false;
  5091	    }
  5092	
  5093	    if (bicycle_gpx_sim_active()) {
  5094	        bicycle_gpx_sim_stop();
  5095	    }
  5096	    map_page_nav_gnss_for_gps(page);
  5097	    page->nav_review = false;
  5098	    if (page->route) {
  5099	        vmap_route_set_review(page->route, false);
  5100	    }
  5101	    if (page->map) {
  5102	        vmap_view_set_arrow_visible(page->map, true);
  5103	        vmap_view_bring_arrow_to_front(page->map);
  5104	    }
  5105	
  5106	    {
  5107	        const char * base = path;
  5108	        const char * slash = strrchr(path, '/');
  5109	        char * dot;
  5110	
  5111	        if (slash && slash[1] != '\0') {
  5112	            base = slash + 1;
  5113	        }
  5114	        lv_snprintf(page->nav_title, sizeof(page->nav_title), "%s", base);
  5115	        dot = strrchr(page->nav_title, '.');
  5116	        if (dot) {
  5117	            *dot = '\0';
  5118	        }
  5119	    }
  5120	
  5121	    pts = (vmap_route_pt_t *)vmap_malloc(
  5122	        (size_t)VMAP_ROUTE_MAX_PTS * sizeof(*pts));
  5123	    if (!pts) {
  5124	        return false;
  5125	    }
  5126	
  5127	    if (!map_page_gpx_load(path, pts, VMAP_ROUTE_MAX_PTS, &kept, &file_n, &len,
  5128	            &true_len)
  5129	        || kept < 2u) {
  5130	        VMAP_NAV_WARN("nav_gpx: no points in %s", path);
  5131	        vmap_free(pts);
  5132	        return false;
  5133	    }
  5134	
  5135	    if (reverse) {
  5136	        map_page_reverse_pts(pts, kept);
  5137	    }
  5138	
  5139	    map_page_gpx_course_clear(page);
  5140	    page->nav_gpx_pts = pts;
  5141	    page->nav_gpx_n = kept;
  5142	    page->nav_gpx_total_m = len;
  5143	    page->nav_gpx_true_m = true_len > len ? true_len : len;
  5144	    page->nav_gpx_reverse = reverse;
  5145	
  5146	    have_fix = bicycle_runtime_poll_fix(&fix);
  5147	    join = map_page_gpx_start_join(page, have_fix ? &fix : NULL, &from_m);
  5148	
  5149	    avg_m = (file_n > 1u) ? (len / (double)(file_n - 1u)) : len;
  5150	    if (avg_m <= MAP_PAGE_GPX_DENSE_AVG_M) {
  5151	        VMAP_NAV_LOG("nav_gpx: %s%s dense avg=%.0fm file=%u pts=%u len=%.0fm win=%.0f%s",
  5152	            path, reverse ? " rev" : "", avg_m, (unsigned)file_n,
  5153	            (unsigned)kept, len, VMAP_NAV_GPX_WINDOW_M,
  5154	            join ? " join" : "");
  5155	        ok = map_page_gpx_load_window(page, from_m, true);
  5156	        if (!ok) {
  5157	            map_page_gpx_course_clear(page);
  5158	        }
  5159	        return ok;
  5160	    }
  5161	
  5162	    VMAP_NAV_LOG("nav_gpx: %s%s sparse avg=%.0fm file=%u pts=%u len=%.0fm win=%.0f%s",
  5163	        path, reverse ? " rev" : "", avg_m, (unsigned)file_n,
  5164	        (unsigned)kept, len, VMAP_NAV_GPX_WINDOW_M,
  5165	        join ? " join" : "");
  5166	    if (join) {
  5167	        ok = map_page_gpx_plan_window(page, (double)fix.longitude,
  5168	            (double)fix.latitude, from_m, false);
  5169	    } else {
  5170	        ok = map_page_gpx_plan_window(page, pts[0].lon, pts[0].lat, 0.0, false);
  5171	    }
  5172	    if (!ok) {
  5173	        map_page_gpx_course_clear(page);
  5174	    }
  5175	    return ok;
  5176	}
