  5199	static void map_page_fit_pts(map_page_t * page, const vmap_route_pt_t * pts,
  5200	    uint32_t n)
  5201	{
  5202	    double min_lon;
  5203	    double max_lon;
  5204	    double min_lat;
  5205	    double max_lat;
  5206	    double cx;
  5207	    double cy;
  5208	    uint32_t i;
  5209	    int z;
  5210	    int32_t w = 0;
  5211	    int32_t h = 0;
  5212	    const int32_t pad = 20;
  5213	
  5214	    if (!page || !page->map || !pts || n < 2u) {
  5215	        return;
  5216	    }
  5217	
  5218	    min_lon = max_lon = pts[0].lon;
  5219	    min_lat = max_lat = pts[0].lat;
  5220	    for (i = 1u; i < n; i++) {
  5221	        if (pts[i].lon < min_lon) {
  5222	            min_lon = pts[i].lon;
  5223	        }
  5224	        if (pts[i].lon > max_lon) {
  5225	            max_lon = pts[i].lon;
  5226	        }
  5227	        if (pts[i].lat < min_lat) {
  5228	            min_lat = pts[i].lat;
  5229	        }
  5230	        if (pts[i].lat > max_lat) {
  5231	            max_lat = pts[i].lat;
  5232	        }
  5233	    }
  5234	
  5235	    cx = (min_lon + max_lon) * 0.5;
  5236	    cy = (min_lat + max_lat) * 0.5;
  5237	    vmap_view_get_buffer_size(page->map, &w, &h);
  5238	
  5239	    for (z = VMAP_ZOOM_MAX; z >= VMAP_ZOOM_MIN; z--) {
  5240	        int32_t x0;
  5241	        int32_t y0;
  5242	        int32_t x1;
  5243	        int32_t y1;
  5244	
  5245	        vmap_view_set_view(page->map, cx, cy, z);
  5246	        (void)vmap_view_geo_to_viewport_raw(page->map, min_lon, min_lat, &x0, &y0);
  5247	        (void)vmap_view_geo_to_viewport_raw(page->map, max_lon, max_lat, &x1, &y1);
  5248	        if (x0 > x1) {
  5249	            int32_t t = x0;
  5250	
  5251	            x0 = x1;
  5252	            x1 = t;
  5253	        }
  5254	        if (y0 > y1) {
  5255	            int32_t t = y0;
  5256	
  5257	            y0 = y1;
  5258	            y1 = t;
  5259	        }
  5260	        if (x0 >= pad && y0 >= pad && x1 < w - pad && y1 < h - pad) {
  5261	            return;
  5262	        }
  5263	    }
  5264	}
