  5266	/**
  5267	 * @brief 在地图上显示 GPX 轨迹（不导航、不模拟定位）。
  5268	 */
  5269	bool map_page_show_gpx(map_page_t * page, const char * path)
  5270	{
  5271	    vmap_route_pt_t * pts;
  5272	    uint32_t kept = 0;
  5273	    uint32_t file_n = 0;
  5274	    double len = 0.0;
  5275	    double true_len = 0.0;
  5276	    char msg[80];
  5277	
  5278	    if (!page || !path || path[0] == '\0') {
  5279	        return false;
  5280	    }
  5281	
  5282	    /* 判死期间**先返回再动状态**：下面 `course_clear()` 会释放旧点列、清窗口
  5283	     * 参数，而 `map_page_gpx_load()` 这时一定会失败 —— 先清后失败等于把一条
  5284	     * 正在用的 GPX 导航拆成"图还在、推进用的点列没了"（Codex R1 P2-9）。
  5285	     * 保持旧状态，等复活后下一次调用再换。 */
  5286	    if (sf32lb_sd_dead != NULL && sf32lb_sd_dead()) {
  5287	        return false;
  5288	    }
  5289	
  5290	    if (bicycle_gpx_sim_active()) {
  5291	        bicycle_gpx_sim_stop();
  5292	    }
  5293	    map_page_nav_gnss_for_gps(page);
  5294	    map_page_gpx_set_title(page, path);
  5295	    map_page_gpx_course_clear(page);
  5296	
  5297	    pts = (vmap_route_pt_t *)vmap_malloc(
  5298	        (size_t)VMAP_ROUTE_MAX_PTS * sizeof(*pts));
  5299	    if (!pts) {
  5300	        return false;
  5301	    }
  5302	
  5303	    if (!map_page_gpx_load(path, pts, VMAP_ROUTE_MAX_PTS, &kept, &file_n, &len,
  5304	            &true_len)
  5305	        || kept < 2u) {
  5306	        vmap_free(pts);
  5307	        return false;
  5308	    }
  5309	    (void)file_n;
  5310	
  5311	    if (!map_page_ensure_route_nav_ex(page, false)) {
  5312	        vmap_free(pts);
  5313	        return false;
  5314	    }
  5315	
  5316	    vmap_route_worker_init();
  5317	    if (vmap_route_worker_busy()) {
  5318	        vmap_free(pts);
  5319	        return false;
  5320	    }
  5321	    map_page_gpx_rejoin_reset(page);
  5322	    vmap_route_worker_cancel();
  5323	    if (page->nav) {
  5324	        vmap_route_nav_stop(page->nav);
  5325	    }
  5326	    vmap_route_trip_reset(&page->nav_trip);
  5327	    map_page_trip_ahead_clear(page);
  5328	    page->nav_trip_active = false;
  5329	    page->nav_top_only = false;
  5330	    page->nav_planning = false;
  5331	    page->nav_replanning = false;
  5332	    page->nav_refine_extend = false;
  5333	    page->nav_arrive_hold = false;
  5334	    page->nav_planned = false;
  5335	    page->nav_gpx_course = true;
  5336	    page->nav_user_set = true;
  5337	    page->nav_review = true;
  5338	
  5339	    vmap_route_apply(page->route, pts, kept, len, NULL, 0);
  5340	    vmap_route_set_review(page->route, true);
  5400	        && vmap_route_trip_waypoint_at(&page->nav_trip, best, &wlon, &wlat)) {
  5401	        double nlon;
  5402	        double nlat;
  5403	        double d_cur;
  5404	        double d_next;
  5405	        double d_seg;
  5406	
  5407	        if (vmap_route_trip_waypoint_at(&page->nav_trip, best + 1u, &nlon,
  5408	                &nlat)) {
  5409	            d_cur = vmap_geo_haversine_m(lon, lat, wlon, wlat);
  5410	            d_next = vmap_geo_haversine_m(lon, lat, nlon, nlat);
  5411	            d_seg = vmap_geo_haversine_m(wlon, wlat, nlon, nlat);
  5412	            if (d_seg > 1.0 && d_cur + d_next <= d_seg * 1.25 + 30.0) {
  5413	                best = best + 1u;
  5414	            }
  5415	        }
  5416	    }
  5417	    return best;
  5418	}
  5419	
  5420	static bool map_page_nav_plan_nearest_gpx(map_page_t * page, double lon,
  5421	    double lat)
  5422	{
  5423	    double dist = 1e300;
  5424	    double along;
  5425	    double from_m;
  5426	    char msg[64];
  5427	
  5428	    along = map_page_gpx_nearest_along(page->nav_gpx_pts, page->nav_gpx_n,
  5429	        lon, lat, &dist);
  5430	    if (page->nav_gpx_total_m - along < 20.0) {
  5431	        lv_pm_notify_show("就近规划", "已接近终点", 2000);
  5432	        return false;
  5433	    }
  5434	
  5435	    from_m = along;
  5436	    if (from_m > VMAP_NAV_GPX_OVERLAP_M) {
  5437	        from_m -= VMAP_NAV_GPX_OVERLAP_M;
  5438	    } else {
  5439	        from_m = 0.0;
  5440	    }
  5441	
  5442	    page->nav_arrive_hold = false;
  5443	    page->nav_gpx_win_start_m = -1e9;
  5444	    page->nav_gpx_win_end_m = -1e9;
  5445	
  5446	    if (page->nav_gpx_sparse) {
  5447	        if (!map_page_gpx_plan_window(page, lon, lat, along, true)) {
  5448	            return false;
  5449	        }
  5450	        page->nav_gpx_sparse = true;
  5451	        lv_pm_notify_show("就近规划", "从最近点向后规划", 2000);
  5452	        VMAP_NAV_LOG("nearest gpx sparse along=%.0f dist=%.0f", along, dist);
  5453	        return true;
  5454	    }
  5455	
  5456	    if (!map_page_gpx_load_window(page, from_m, false)
  5457	        && !map_page_gpx_load_window(page, from_m, true)) {
  5458	        return false;
  5459	    }
  5460	    {
  5461	        const vmap_route_nav_state_t * st =
  5462	            page->nav ? vmap_route_nav_state(page->nav) : NULL;
  5463	        const double off = map_page_gpx_off_threshold(page);
  5464	
  5465	        if (st && st->active && dist > off
  5466	            && map_page_nav_gpx_rejoin_begin(page, st, lon, lat)) {
  5467	            lv_pm_notify_show("就近规划", "正在接回路书", 2000);
  5468	            VMAP_NAV_LOG("nearest gpx rejoin along=%.0f dist=%.0f", along, dist);
  5469	            return true;
  5470	        }
  5471	    }
  5472	    snprintf(msg, sizeof(msg), "路线 %.1f / %.1f km",
  5473	        along / 1000.0,
  5474	        (page->nav_gpx_true_m > page->nav_gpx_total_m
  5475	            ? page->nav_gpx_true_m : page->nav_gpx_total_m) / 1000.0);
  5476	    lv_pm_notify_show("就近规划", msg, 2500);
  5477	    VMAP_NAV_LOG("nearest gpx dense along=%.0f dist=%.0f", along, dist);
  5478	    return true;
  5479	}
