  5614	/**
  5615	 * @brief cover pop 后恢复渲染；已有画布只 invalidate。
  5616	 */
  5617	void map_page_resume_after_cover(map_page_t * page)
  5618	{
  5619	    uint32_t rev = 0;
  5620	
  5621	    if (!page) {
  5622	        return;
