  1685	    }
  1686	
  1687	  syslog(LOG_ERR,
  1688	         "SD: unstick failed (%s) r1=0x%lx; defer re-identify to background\n",
  1689	         mute ? "card mute, CMD13 no response" : "card idle after I/O fail",
